mapper.select:
select br.patient_id as patientId, ifnull(sum(br.receivable_amount), 0) as billTotalOriginalPrice, ifnull(sum(br.privilege_amount), 0) as billTotalPrivilegePrice, ifnull(sum(br.actual_receivable_amount), 0) as billTotalActualPrice, ifnull(sum(br.received_amount), 0) as billTotalReceivedPrice, ifnull(sum(br.debt_amount), 0) as billTotalArrears from bill_record br where inservice = true and br.patient_id in
#{patientId}
group by br.patient_id

select br.* from bill_record br where inservice = true and
br.treatment_record_id in

    #{treatmentId}

select br.treatment_record_id as id, br.patient_id as patientId, r.first_visit as firstVisit, r.dentist_id as dentistId, tr.treat_start_time as treatStartTime from bill_record br left join treatment_record tr on tr.patient_id = br.patient_id and tr.id = br.treatment_record_id left join registered r on r.patient_id = br.patient_id and r.id = tr.registered_id where date_format(br.crt_time, '%Y-%m-%d') = date_format(#{currentDate}, '%Y-%m-%d')
and br.org_id = #{orgId}
group by br.treatment_record_id, br.patient_id, r.first_visit, r.dentist_id, treat_start_time order by tr.treat_start_time desc

SELECT
SUM( IFNULL( br.actual_receivable_amount, 0 ) ) AS actualReceivedAmountCompleted
FROM
bill_record br

    AND br.inservice = 1

        AND DATE_FORMAT(br.crt_time, '%Y-%m') = #{query.businessDate}


        AND DATE_FORMAT(br.crt_time, '%Y') = #{query.businessDate}


        AND br.org_id IN

            #{item}

SELECT IFNULL(SUM( odpr.actual_receivable ) + SUM( odpr.coupon_workload ), 0) AS workloadAmountCompleted FROM order_detail_pay_record odpr
AND odpr.inservice = 1
AND DATE_FORMAT(odpr.crt_time, '%Y-%m') = #{query.businessDate}
AND DATE_FORMAT(odpr.crt_time, '%Y') = #{query.businessDate}
AND odpr.order_detail_id IN ( SELECT od.id FROM order_detail od
AND od.inservice = 1 AND od.executor_id IS NOT NULL
AND od.org_id IN
#{item}
)

SELECT
SUM( br.actual_receivable_amount ) AS actualReceivedAmountCompleted
FROM
bill_record br

    AND br.inservice = 1

        AND br.org_id = #{query.orgId}


        AND DATE_FORMAT(br.crt_time, '%Y-%m') >= #{query.startDate}


        AND DATE_FORMAT(br.crt_time, '%Y-%m') <= #{query.endDate}

select bd.billRecordId, bd.billDate, bd.clinicId, bd.dentistId, bd.billActualAmount, bd.billReceivedAmount, bd.billDebtAmount, bd.orderDetailId, bd.itemType, bd.billingItemId, case bd.itemType when 0 then ifnull(bd.billingItemName,bt.name) when 1 then ifnull(bd.billingItemName,bot.name) end as billingItemName, case bd.itemType when 0 then bt.english_name when 1 then bot.english_name end as billingItemEnglishName, bd.price, case bd.itemType when 0 then bt.unit when 1 then bot.unit end as unit, bd.quantity, bd.receivableAmount, bd.toothBit, bd.privilegeAmount, bd.actualAmount from ( select br.id as billRecordId, date_format(br.crt_time, '%Y-%m-%d %H:%i') as billDate, br.org_id as clinicId, tr.dentist_id as dentistId, br.actual_receivable_amount as billActualAmount, br.received_amount as billReceivedAmount, br.debt_amount as billDebtAmount, od.orderDetailId, od.itemType, od.billingItemId, od.billingItemName, od.price, od.quantity, od.receivableAmount, od.toothBit, od.privilegeAmount, od.actualAmount from bill_record br left join treatment_record tr on br.treatment_record_id = tr.id left join ( select od.id as orderDetailId, odpr.bill_record_id as billId, od.order_record_id as orderId, od.type as itemType, od.billing_item_id as billingItemId, od.billing_item_name as billingItemName, od.price as price, od.quantity as quantity, od.receivable_amount as receivableAmount, od.tooth_bit as toothBit, ifnull(odpr.privilege_amount, 0) as privilegeAmount, ifnull(odpr.actual_receivable, 0) as actualAmount from order_detail od left join order_detail_pay_record odpr on od.id = odpr.order_detail_id ) od on od.billId = br.id and od.orderId = br.order_record_id
and br.inservice = 1 and br.patient_id = #{patientId}
and br.id in
#{item}
) bd LEFT JOIN base_tariff bt on bt.id = bd.billingItemId LEFT JOIN base_oral_tariff bot on bot.id = bd.billingItemId

select billId, billDate, billNum, patientId, regDentistId, totalOriginalAmount, totalActualAmount, totalActualAmount-received_amount AS billReceivableAmount from ( select br.id as billId, date_format(br.crt_time, '%Y-%m-%d') as billDate, br.bill_number as billNum, br.patient_id as patientId, tr.dentist_id as regDentistId, br.receivable_amount as totalOriginalAmount, if(date_format(br.privilege_date, '%Y-%m-%d') > date_format(#{query.queryDate}, '%Y-%m-%d'), br.receivable_amount, br.actual_receivable_amount) as totalActualAmount, ifnull(bpr.received_amount, 0) received_amount from bill_record br left join treatment_record tr on br.treatment_record_id = tr.id LEFT JOIN ( SELECT bpr.bill_record_id,sum(bpr.received_amount) received_amount FROM bill_pay_record bpr WHERE bpr.inservice=true AND date_format(bpr.crt_time, '%Y-%m-%d') <= #{query.queryDate} GROUP BY bpr.bill_record_id ) bpr on br.id=bpr.bill_record_id
and br.inservice = true
and br.org_id = #{query.orgId}
and date_format(br.crt_time, '%Y-%m-%d') <= #{query.queryDate}
and tr.dentist_id in
#{item}
order by br.crt_time desc, br.debt_amount desc ) t where totalActualAmount>received_amount

select IFNULL(sum(privilege_amount),0)
from bill_record
where order_record_id in (
    select behdr.associate_record_id as orderRecordId
    from bill_exception_handle_record behr
             left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
    where operate_type = 2
      and date_format(behr.crt_time, '%Y-%m') = #{query.queryDate}
)  and org_id = #{query.orgId}
and date_format(crt_time, '%Y-%m') = #{query.queryDate}

select IFNULL(sum(privilege_amount),0)
from bill_record
where date_format(crt_time, '%Y-%m') =  #{query.queryDate}
  and date_format(privilege_date, '%Y-%m') =  #{query.queryDate}
  and org_id = #{query.orgId}

select IFNULL(sum(receivable_amount),0)
from bill_record
where order_record_id in (
    select behdr.associate_record_id as orderRecordId
    from bill_exception_handle_record behr
             left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
    where operate_type = 2
      and date_format(behr.crt_time, '%Y-%m') =#{query.queryDate}
)
  and org_id = #{query.orgId}
  and date_format(crt_time, '%Y-%m') = #{query.queryDate}

select IFNULL(sum(receivable_amount),0)
from bill_record
where date_format(crt_time, '%Y-%m') = #{query.queryDate}
and org_id =#{query.orgId}

select IFNULL(sum(bpr.received_amount),0)
from bill_pay_record bpr
left join bill_record br on br.id = bpr.bill_record_id
where
br.org_id = #{query.orgId}
and bpr.id in (
    select behdr.associate_record_id as billPayRecordId
    from bill_exception_handle_record behr
             left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
    where operate_type = 1
      and date_format(behr.crt_time, '%Y-%m') = #{query.queryDate}
)
and date_format(bpr.crt_time, '%Y-%m') = #{query.queryDate}
and date_format(br.crt_time, '%Y-%m') = #{query.queryDate}

select IFNULL(sum(bpr.received_amount),0)
from bill_pay_record bpr
         left join bill_record br on bpr.bill_record_id = br.id
where date_format(bpr.crt_time, '%Y-%m') = #{query.queryDate}
  and date_format(br.crt_time, '%Y-%m') = #{query.queryDate}
  and br.org_id = #{query.orgId}

select IFNULL(sum(amount),0)
from bill_pay_detail_record bpdr
where date_format(bpdr.crt_time, '%Y-%m') = #{query.queryDate}
  and bpdr.account_item_id in (23, 26) and bpdr.inservice = 1
  and bpdr.bill_pay_record_id in (
    select bpr.id
    from bill_pay_record bpr
    where date_format(bpr.crt_time, '%Y-%m') = #{query.queryDate}
      and bpr.bill_record_id in (
        select br.id
        from bill_record br
        where br.org_id = #{query.orgId}
          and date_format(br.crt_time, '%Y-%m') = #{query.queryDate}
    ) and bpr.inservice = 1
)

select distinct order_record_id
from bill_record br
where not exists (
    select behdr.associate_record_id as orderRecordId
    from bill_exception_handle_record behr
    left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
    where operate_type = 2

        and date_format(behr.crt_time, '%Y-%m') = #{query.queryDate}

    and br.order_record_id = behdr.associate_record_id
)

    AND br.org_id IN

        #{item}



    and date_format(crt_time, '%Y-%m') = #{query.queryDate}
    and date_format(privilege_date, '%Y-%m') =  #{query.queryDate}
